      --bg-accent: #121a31;
      --panel: rgba(20, 28, 52, 0.9);
      --panel-border: rgba(156, 173, 255, 0.2);
      --text: #eef2ff;
      --muted: #b6c0e0;
      --highlight: #8ab4ff;
      --highlight-strong: #a78bfa;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(138, 180, 255, 0.14), transparent 32%),
        linear-gradient(180deg, #10172d 0%, var(--bg) 50%, #070b16 100%);
      color: var(--text);
    }

    main {
      width: min(860px, calc(100% - 2rem));
      margin: 0 auto;
      padding: 4rem 0 5rem;
    }

    .hero {
      margin-bottom: 2rem;
      text-align: center;
    }

    .eyebrow {
      display: inline-block;
      margin-bottom: 1rem;
      padding: 0.35rem 0.8rem;
      border: 1px solid rgba(138, 180, 255, 0.25);
      border-radius: 999px;
      background: rgba(138, 180, 255, 0.08);
      color: var(--highlight);
      font-size: 0.85rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
