      margin: 0 0 0.75rem;
      font-size: clamp(2.4rem, 5vw, 4rem);
      line-height: 1.05;
    }

    .hero p {
      max-width: 42rem;
      margin: 0 auto;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.7;
    }

    .faq {
      display: grid;
      gap: 1rem;
    }

    .example {
      border: 1px solid var(--panel-border);
      border-radius: 20px;
      background: linear-gradient(180deg, rgba(25, 36, 69, 0.95), rgba(14, 21, 40, 0.92));
      box-shadow: var(--shadow);
      overflow: clip;
      backdrop-filter: blur(14px);
    }

    .question {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1.25rem 1.4rem;
      border: 0;
      background: transparent;
      color: inherit;
      text-align: left;
      font: inherit;
      font-size: 1.05rem;
      font-weight: 650;
      cursor: pointer;
    }

