      background: rgba(138, 180, 255, 0.08);
      outline: none;
    }

    .question-text {
      line-height: 1.4;
    }

    .icon {
      flex: none;
      width: 2rem;
      height: 2rem;
      display: grid;
      place-items: center;
      border-radius: 999px;
